    op_cozo_store::system_graph_snapshot_digest(&snapshot)?;
    atomic_write(&output, &serde_json::to_vec_pretty(&snapshot)?)?;
    println!(
        "{}: {} nodes, {} edges; prepared source only",
        namespace,
        snapshot.nodes.len(),
120→        snapshot.edges.len()
    );
    Ok(())
}

