                a = 'Deny',
                p = '*',
                o = $operation
            deny_rule[r] :=
                *compliance_rule{plugin: p, op: o, action: a, reason: r},
740→                a = 'Deny',
                p = $plugin,
                o = '*'
            deny_rule[r] :=
                *compliance_rule{plugin: p, op: o, action: a, reason: r},
                a = 'Deny',
                p = '*',
                o = '*'
